export function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.grid).split('|||').map(p=>`<path d="${p}"/>`).join('')}</svg>`}
export const badge=(text,tone='neutral')=>`<span class="pill tone-${esc(tone)}">${esc(text)}</span>`;
export function avatar(p,size=''){return `<span class="avatar ${p.type==='agent'?'avatar-agent':''} ${esc(size)}">${p.type==='agent'?icon('bot',size==='lg'?24:17):esc(p.initials||p.name?.split(' ').map(x=>x[0]).slice(0,2).join('')||'?')}</span>`}
export const progress=(value,tone='purple')=>`<div class="progress-track" role="progressbar" aria-valuenow="${Math.round(Number(value)||0)}" aria-valuemin="0" aria-valuemax="100"><span class="progress-fill ${esc(tone)}" style="width:${Math.max(0,Math.min(100,Number(value)||0))}%"></span></div>`;
export const empty=(title,description)=>`<div class="empty"><span class="empty-icon">${icon('check',28)}</span><h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;
export const fmt=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(Number(n)||0);
export const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(n)||0);
